    MPI_Comm_size(MPI_COMM_WORLD, &size); // 进程总数
    srand(time(NULL) + rank); // 给每个进程设置不同的随机种子

    start_time = MPI_Wtime(); // 记录并行计算开始时间

    // OpenMP并行段
    #pragma omp parallel
    {
        int count_private = 0; // 各线程私有count

        // 静态分配任务：不同进程处理不同下标的试验
        #pragma omp for
