                count_private++;
            }
        }

        #pragma omp atomic // 原子操作，防止多个线程并发写count出错
        count += count_private;
    }

    // 所有进程的count加和，只有rank=0的进程获得最终global_count
    MPI_Reduce(&count, &global_count, 1, MPI_INT, MPI_SUM, 0, MPI_COMM_WORLD);

