{
    taskENTER_CRITICAL();
    if (waitqueue->head != NULL) {
        WaitQueueEntry_t* entry = waitqueue->head;
        waitqueue->head = entry->next;
        if (waitqueue->head == NULL) {
            waitqueue->tail = NULL;
        }
        // Notify the waiting task
        xTaskNotifyGive(entry->task);
    }
    taskEXIT_CRITICAL();
